  ('L049', 'Oi{dono}, tudo bem? Aqui é da Psy Comunic, especialistas em criação de marcas de sucesso. Cheguei no seu perfil procurando quem está à frente de Atacado de Brusque. Vi que vocês lançam coleção toda semana e têm mais de 100 mil seguidores. A gente refaz a operação inteira: a loja de atacado, a loja de varejo e o aplicativo da marca, numa plataforma que integra marketplaces, ERP, transportadoras e mais. Faz sentido te mostrar como ficaria?'),
  ('L050', 'Oi{dono}, tudo bem? Aqui é da Psy Comunic, especialistas em criação de marcas de sucesso. Cheguei no seu perfil procurando quem está à frente de Miss Glamour. Vi que vocês estão há 15 anos no atacado feminino no Catarina Shopping. A gente monta a operação inteira: a loja de atacado com pedido mínimo, tabela por CNPJ e área do lojista, e o aplicativo da marca, numa plataforma que integra marketplaces, ERP, transportadoras e mais. Faz sentido te mostrar como ficaria?'))
update prospeccao p
   set mensagem_abertura = nova.mensagem
  from nova
 where p.codigo = nova.codigo
   and p.mensagem_abertura is distinct from nova.mensagem;

/* O canal já era esse nas 50, e agora é regra: toda abordagem desta
   lista acontece no Instagram. Escrito no banco para a tela não ter de
   supor. */
update prospeccao set canal = 'Instagram DM' where canal is distinct from 'Instagram DM';
